/* Operator-only catalog editor. Game forwards to Progress's transaction owner. */
(() => {
 const panel=document.getElementById('upgradePrices'),status=panel.querySelector('[role=status]');let economy=null,busy=false,operation=null;
 const tracks=[['damage-machine-gun','Machine Gun'],['damage-flamethrower','Flamethrower'],['damage-mortar','Mortar'],['damage-tesla-coil','Tesla Coil']];
 panel.querySelector('tbody').innerHTML=tracks.map(([id,name])=>`<tr><th scope="row">${name}</th>${[2,3,4].map(l=>`<td><input aria-label="${name} T${l} price" data-price-track="${id}" data-price-level="${l}" type="number" min="0" max="100000" step="1"></td>`).join('')}<td data-total="${id}"></td></tr>`).join('');
 const fields=[...panel.querySelectorAll('[data-price-track]')];
 function collect(){const prices={};for(const input of fields){const n=Number(input.value);if(!input.value||!Number.isInteger(n)||n<0||n>100000)throw Error('Enter all 12 integer prices (0–100,000).');(prices[input.dataset.priceTrack]||={})[input.dataset.priceLevel]=n;}return prices;}
 function totals(){try{const prices=collect();for(const [track] of tracks)panel.querySelector(`[data-total="${track}"]`).textContent=Object.values(prices[track]).reduce((a,b)=>a+b,0).toLocaleString();panel.querySelector('[data-grand-total]').textContent=Object.values(prices).flatMap(Object.values).reduce((a,b)=>a+b,0).toLocaleString();}catch{}}
 function populate(prices){for(const input of fields)input.value=prices[input.dataset.priceTrack][input.dataset.priceLevel];totals();}
 async function request(body){const response=await fetch('api/economy',body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{cache:'no-store'});const value=await response.json();if(!response.ok||value.status!=='ready'||value.contract!=='photon.progress.economy'||value.version!==1)throw Error(value.error||'Price catalog unavailable');return value;}
 async function load(){try{economy=await request();populate((economy.pending_catalog||economy.catalog).prices);status.textContent=`Active catalog ${economy.active}${economy.pending?' · staged catalog '+economy.pending+' activates at the next match':''}.`;panel.querySelector('[data-save-prices]').disabled=false;}catch(e){status.textContent=e.message;}}
 fields.forEach(input=>input.addEventListener('input',()=>{operation=null;totals();}));
 panel.querySelector('[data-save-prices]').onclick=async()=>{if(busy||!economy)return;busy=true;try{const prices=collect();const intent=JSON.stringify([prices,economy.revision]);if(operation?.intent!==intent)operation={intent,id:crypto.randomUUID()};economy=await request({prices,revision:economy.revision,operation_id:operation.id});operation=null;status.textContent=economy.pending?'Saved; staged for the next match.':'Saved and active in the unreserved lobby.';}catch(e){status.textContent=e.message;}finally{busy=false;}};
 fetch('api/state',{cache:'no-store'}).then(r=>r.json()).then(s=>{const preview=s.next_match;panel.querySelector('[data-affordability]').textContent=preview?.status==='ready'?`Selected presets: ${preview.survival_credits_before_cue.toLocaleString()} credits per player across one full-clear match at each of L1–L3. This is a reference, not a predicted human outcome.`:'Selected-preset affordability unavailable.';}).catch(()=>{panel.querySelector('[data-affordability]').textContent='Selected-preset affordability unavailable.';});
 load();
})();
